import type {SidebarsConfig} from '@docusaurus/plugin-content-docs';
import {SUBJECTS} from './src/data/subjects';

/**
 * Dedicated per-subject sidebars keep each subject focused like standalone documentation.
 * Every subject in `src/data/subjects.ts` automatically gets an autogenerated sidebar
 * mapped to `docs/<subject.id>/`.
 */
const subjectSidebars: SidebarsConfig = Object.fromEntries(
  SUBJECTS.map((subject) => [
    `${subject.id}Sidebar`,
    [
      {
        type: 'autogenerated' as const,
        dirName: subject.id,
      },
    ],
  ]),
);

const sidebars: SidebarsConfig = {
  guideSidebar: [
    'intro',
    'sample-lesson',
    'credits',
  ],
  ...subjectSidebars,
};

export default sidebars;
